python3 - <<'PY'
p='src/types/checker/functions/call_validation.rs'
s=open(p).read()
old = """            // An ELEMENT of a property is a place too — `set($obj->items[1])` is ordinary php —
            // and `ref_place_args` reads and writes back a chain of them. The receiver has to be
            // a place this checker already accepts, so the recursion bottoms out on a property
            // or a static property rather than on any expression.
            ExprKind::ArrayAccess { array, .. }
                if matches!(
                    array.kind,
                    ExprKind::PropertyAccess { .. } | ExprKind::StaticPropertyAccess { .. }
                ) =>
            {
                Ok(matches!(
                    self.infer_type(array, env)?.codegen_repr(),
                    PhpType::Array(_) | PhpType::AssocArray { .. }
                ))
            }"""
new = """            // An ELEMENT of a property — `set($obj->items[1])` — stays REFUSED. php allows it,
            // but the by-reference argument lowering resolves a cell address only for an element
            // of a plain LOCAL, and `ref_place_args`' read/write-back does not fire for it
            // either: accepting the shape produced a call that ran and dropped the write in
            // silence, which is worse than the diagnostic. The refusal names the parameter."""
assert s.count(old)==1
open(p,'w').write(s.replace(old,new))
print('property-element acceptance reverted')
